/******/ (() => { // webpackBootstrap
jQuery(document).ready(function ($) {
    $('.wa-product-compare-button').on('click', function (e) {
        var $this = $(this);
        if (wooAssistantAjax) return;
        wooAssistantAjax = true;

        $.post(
            WooAssistant.ajaxUrl,
            {
                nonce: WooAssistant.ajaxNonce,
                action: "wa_product_compare_add_remove",
                product_id: $this.data('id')
            }
        )
            .done(function (data) {
                if (data.data.status === 'added')
                    $this.addClass('wa-button-remove');
                else if (data.data.status === 'removed')
                    $this.removeClass('wa-button-remove');
                else if (data.data.status === 'max_exceeded')
                    alert(WooAssistantProductCompare.maxExceededMessage.replace('%number%', data.data.count));

                if ($this.data('action') === 'refresh')
                    window.location.reload(true);

                if (data.data?.redirect && data.data.redirect !== '')
                    window.location.href = data.data.redirect;
            })
            .fail(function (xhr, status, error) {
                if (xhr.responseJSON?.data?.refresh)
                    setTimeout(function () {
                        window.location.reload(true);
                    }, 3000);
            })
            .always(function () {
                wooAssistantAjax = false;
            });
    });
});
/******/ })()
;